// ---------------------------------------------------------------------------
// Runtime codecs
// ---------------------------------------------------------------------------

export const PreferencesCodecs = {
  theme         : recordCodecs.json<ThemeData>({ validator: moduleValidators.validateThemeData }),
  locale        : recordCodecs.json<LocaleData>({ validator: moduleValidators.validateLocaleData }),
  privacy       : recordCodecs.json<PrivacyData>({ validator: moduleValidators.validatePrivacyData }),
  notification  : recordCodecs.json<NotificationData>({ validator: moduleValidators.validateNotificationData }),
  accessibility : recordCodecs.json<AccessibilityData>({ validator: moduleValidators.validateAccessibilityData }),
  food          : recordCodecs.json<FoodData>({ validator: moduleValidators.validateFoodData }),
  travel        : recordCodecs.json<TravelData>({ validator: moduleValidators.validateTravelData }),
  communication : recordCodecs.json<CommunicationData>({ validator: moduleValidators.validateCommunicationData }),
} as const;

// ---------------------------------------------------------------------------
// Typed module
// ---------------------------------------------------------------------------

export const PreferencesModule = defineModule({
  definition : PreferencesDefinition,
  codecs     : PreferencesCodecs,
});

